import React from 'react'
import Chart from 'react-apexcharts'
import moment from 'moment'

const MonthlyExpensesChart = ({ apiData, currencyInfo }) => {
  function thousands_separators(num) {
    var num_parts = num.toString().split(".");
    num_parts[0] = num_parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    console.log(num_parts, "nnnnnmmm")
    return num_parts.join(".");
  }
  const optionsExpenses = {
    chart: {
      id: 'expensesOverview',
      group: 'expensesOverview',
      type: 'line',
      stacked: false,
      height: 600,
      events: {
        mouseMove: function (event, chartContext, config) {
          // The last parameter config contains additional information like `seriesIndex` and `dataPointIndex` for cartesian charts.
        }
      }
    },
    dataLabels: {
      enabled: false,
    },
    stroke: {
      width: [4, 1, 1],
      curve: 'smooth'
    },
    title: {
      text: 'Expenses Overview',
      align: 'left',
      offsetX: 110
    },
    colors: ['#008FFB', '#00E396'],
    yaxis: [
      {
        seriesName: 'Expenses',
        axisTicks: {
          show: true,
        },
        axisBorder: {
          show: true,
          color: '#008FFB'
        },
        labels: {
          style: {
            colors: '#141414',
          },
          formatter: (value) => {
            let amount;

            if (currencyInfo.toLowerCase() == "₹" || currencyInfo.toLowerCase() == 'inr') {
              amount = new Intl.NumberFormat('en-IN').format(parseFloat(value).toFixed(0))
            }
            else {
              amount = thousands_separators(parseFloat(value).toFixed(0))
            }
            return currencyInfo + "  " + amount
            // new Intl.NumberFormat('en-IN', { style: 'currency', currency: currencyInfo }).format(value)
          },
          minWidth: 80
        },
        title: {
          text: "Amount",
          style: {
            color: '#141414',
          }
        },
        tooltip: {
          theme: "dark"
        }
      }
    ],
    legend: {
      horizontalAlign: 'left',
      offsetX: 40,
    }
  }

  const getSeriesData = () => {
    let ExpenseSeriesData = []

    apiData.forEach(d => {
      let currDateTotalExpense = 0

      d.expenses && d.expenses.length > 0 && d.expenses[0].ledgers && d.expenses[0].ledgers.forEach(ledger => {
        currDateTotalExpense += Object.values(ledger)[0]
      })

      ExpenseSeriesData.push({
        "x": moment(d.trandate).format("MMM-YYYY"),
        "y": currDateTotalExpense
      })
    })

    return [{
      name: "Expenses",
      data: ExpenseSeriesData,
      type: 'line'
    }]
  }

  return <Chart options={optionsExpenses} series={getSeriesData()} type="line" height={600} />

}

export default MonthlyExpensesChart