import React from 'react'
import moment from 'moment'
import Chart from "react-apexcharts";

const MonthlyRevenueChart = ({ apiData, currencyInfo }) => {
  function thousands_separators(num) {
    var num_parts = num.toString().split(".");
    num_parts[0] = num_parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    console.log(num_parts, "nnnnnmmm")
    return num_parts.join(".");
  }
  const optionsFinancial = {
    chart: {
      id: 'financialOverview',
      group: 'monthlyOverview',
      type: 'line',
      stacked: false,
      height: 600,
      events: {
        mouseMove: function (event, chartContext, config) {
          // The last parameter config contains additional information like `seriesIndex` and `dataPointIndex` for cartesian charts.
        }
      }
    },
    dataLabels: {
      enabled: false,
    },
    stroke: {
      width: [4, 1, 1],
      curve: 'smooth'
    },
    title: {
      text: 'Revenue',
      align: 'left',
      offsetX: 110
    },

    colors: ['#008FFB', '#00E396', '#F15B46'],
    yaxis: [
      {
        seriesName: 'Revenue',
        axisTicks: {
          show: true,
        },
        axisBorder: {
          show: true,
          color: '#008FFB'
        },
        labels: {
          style: {
            colors: '#141414',
          },
          formatter: (value) => {
            let amount;

            if (currencyInfo.toLowerCase() == "₹" || currencyInfo.toLowerCase() == 'inr') {
              amount = new Intl.NumberFormat('en-IN').format(parseFloat(value).toFixed(0))
            }
            else {
              amount = thousands_separators(parseFloat(value).toFixed(0))
            }
            return currencyInfo + "  " + amount
            // new Intl.NumberFormat('en-IN', { style: 'currency', currency: currencyInfo }).format(value)
          },
          minWidth: 80
        },
        title: {
          text: "Rupees",
          style: {
            color: '#141414',
          }
        },
        tooltip: {
          theme: "dark"
        }
      }
    ],
    legend: {
      horizontalAlign: 'left',
      offsetX: 40,
    }
  }

  const getSeriesData = () => {
    let RevenueSeriesData = []

    apiData.forEach(md => {
      let totalMonthlyRev = 0

      md.revenues.forEach(mrev => {
        if (mrev == null) return
        totalMonthlyRev += Object.values(mrev)[0]
      })

      RevenueSeriesData.push({
        "x": moment(md.trandate).format("MMM-YYYY"),
        "y": totalMonthlyRev
      })

    })

    return {
      FinancialSeries: [
        {
          name: "Revenue",
          data: RevenueSeriesData,
          type: 'line'
        }
      ]
    }
  }

  return (
    <Chart options={optionsFinancial} series={getSeriesData().FinancialSeries} type="line" height={600} />)
}

export default MonthlyRevenueChart