import React, { useEffect, useState } from 'react'
import { Table, Button, Badge, Menu, Modal } from 'antd';
import { DownloadOutlined, FilePdfOutlined } from '@ant-design/icons';
import GetApiData from '../utils/GetApiData';
import { Viewer } from '@react-pdf-viewer/core';//needed
import PDFViewer from 'pdf-viewer-reactjs';//needed

const DailyOutstandingsTable = ({ data, apiData, currencyInfo, apiHost }) => {
  const [isPdfVisible, setIsPdfVisible] = useState(false);
  const [objUrl, setObjUrl] = useState(null);
  const [base64String, setBase64String] = useState(null);
  const base64ToArrayBuffer = (data) => {
    var bString = window.atob(data);
    var bLength = bString.length;
    var bytes = new Uint8Array(bLength);
    for (var i = 0; i < bLength; i++) {
      var ascii = bString.charCodeAt(i);
      bytes[i] = ascii;
    }
    return bytes;
  };
  useEffect(async () => {
    console.log(apiData, "hosttttttttt")
    let FromDate = apiData[0].trandate
    let ToDate = apiData[apiData.length - 1].trandate;
    let organization_id = localStorage.getItem("organisationId") ? +localStorage.getItem("organisationId") : apiData ? apiData[0].organizationId : null
    let unit_id = apiData[0].unitId ? apiData[0].unitId : 0;
    console.log(unit_id, "uuuuuunnntn")
    GetApiData.downloadOutstandingReport({
      FromDate,
      ToDate,
      organization_id,
      unit_id,
      apiHost
    })
      .then(data => {
        setBase64String(data);
        var bufferArray = base64ToArrayBuffer(data);
        var blobStore = new Blob([bufferArray], { type: "application/pdf" });
        if (window.navigator && window.navigator.msSaveOrOpenBlob) {
          window.navigator.msSaveOrOpenBlob(blobStore);
          return;
        }
        var data = window.URL.createObjectURL(blobStore);
        console.log(data, "urlllll")
        setObjUrl(data)
      }).catch(err => {
        console.log("eeeeeeeee", err)
      })
  }, [])


  const downloadPdf = () => {

    GetApiData.fndownloadPDF(base64String, "outStandingReport.pdf")

  }
  function thousands_separators(num) {
    var num_parts = num.toString().split(".");
    num_parts[0] = num_parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    console.log(num_parts, "nnnnnmmm")
    return num_parts.join(".");
  }
  const getTableCols = () => {
    let retCols = []

    retCols.push({
      title: "Company",
      key: "company",
      dataIndex: "company",
      // fixed: "left",
      fixed: window.innerWidth < 768 ? '' : 'left',
      // width: 120
      width: window.innerWidth < 768 ? 100 : 120,
      render: (text) => {
        return (<span style={{ fontSize: window.innerWidth < 768 ? "12px" : "15px" }}  >{text}</span>)
      }
    })

    apiData && apiData.length > 0 && apiData.forEach(dd => {
      retCols.push({
        title: dd['trandate'],
        key: `outstanding-${dd['trandate']}`,
        dataIndex: `outstanding-${dd['trandate']}`,
        // width: 160,
        width: window.innerWidth < 768 ? 110 : 160,
        align: 'right',
        render: ((text, rec, idx) => {
          let amount;

          if (currencyInfo.toLowerCase() == "₹" || currencyInfo.toLowerCase() == 'inr') {
            amount = new Intl.NumberFormat('en-IN').format(parseFloat(text).toFixed(0))
          }
          else {
            amount = thousands_separators(parseFloat(text).toFixed(0))
          }
          return (<span style={{ fontSize: window.innerWidth < 768 ? "12px" : "15px" }}>
            {
              currencyInfo + " " + amount
            }
            {/* {new Intl.NumberFormat('en-IN', { style: 'currency', currency: currencyInfo }).format(text)} */}
          </span>)
        }),
      })
    })

    retCols.push({
      title: 'Total',
      key: 'total',
      dataIndex: 'total',
      // fixed: 'right',
      fixed: window.innerWidth < 768 ? '' : 'right',
      align: 'right',
      // width: 160,
      width: window.innerWidth < 768 ? 120 : 160,
      render: ((text, rec, idx) => {
        let amount;

        if (currencyInfo.toLowerCase() == "₹" || currencyInfo.toLowerCase() == 'inr') {
          amount = new Intl.NumberFormat('en-IN').format(parseFloat(text).toFixed(0))
        }
        else {
          amount = thousands_separators(parseFloat(text).toFixed(0))
        }
        return (<span style={{ fontSize: window.innerWidth < 768 ? "12px" : "15px" }}>
          {
            currencyInfo + " " + amount
          }
          {/* {new Intl.NumberFormat('en-IN', { style: 'currency', currency: currencyInfo }).format(text)} */}
        </span>)

      }),
    })

    return retCols

  }

  const getTableData = () => {
    let tableDataArray = []
    let insertedModeList = []
    //insertedModeList[0] is array of pay modes
    insertedModeList[0] = []
    //insertedModeList[1] is running total amount against pay mode at insertedModeList[0]
    insertedModeList[1] = []
    let daywiseTotalRowObj = {
      'key': 'total',
      'company': 'Total',
    }

    apiData && apiData.length > 0 && apiData.forEach(d => {
      let currDate = d.trandate
      let daywiseTotal = 0
      d.outstandings.forEach(o => {
        let outCompany = Object.keys(o)[0]
        let outAmt = Object.values(o)[0]
        let rowObj = {}

        if (insertedModeList[0].indexOf(outCompany) < 0) {
          insertedModeList[0].push(outCompany)
          rowObj['key'] = outCompany
          rowObj['company'] = outCompany
          insertedModeList[1][insertedModeList[0].indexOf(outCompany)] = outAmt
        } else {
          rowObj = tableDataArray[insertedModeList[0].indexOf(outCompany)]
          insertedModeList[1][insertedModeList[0].indexOf(outCompany)] += outAmt
        }

        rowObj[`outstanding-${currDate}`] = outAmt
        tableDataArray[insertedModeList[0].indexOf(outCompany)] = rowObj
        daywiseTotal += outAmt
      })
      daywiseTotalRowObj[`outstanding-${currDate}`] = daywiseTotal
    })

    tableDataArray.push(daywiseTotalRowObj)

    tableDataArray.forEach((t, tIdx) => {
      let tKeysList = Object.keys(t)
      apiData && apiData.length > 0 && apiData.forEach(ad => {
        if (!tKeysList.includes(`outstanding-${ad.trandate}`)) {
          tableDataArray[tIdx][`outstanding-${ad.trandate}`] = 0
        }
      })

      tableDataArray[tIdx]['total'] = insertedModeList[1][tIdx]

      if (tableDataArray.length == tIdx + 1) {
        tableDataArray[tIdx]['total'] = insertedModeList[1].reduce((a, b) => a + b, 0)
      }
    })
    // console.log(tableDataArray)
    return tableDataArray
  }
  const fnDownloadReport = (pdfAction) => {
    console.log(apiHost, "hosttttttttt")
    let FromDate = apiData[0].trandate
    let ToDate = apiData[apiData.length - 1].trandate;
    let organization_id = localStorage.getItem("organisationId");
    let unit_id = apiData[0].unitId;
    GetApiData.downloadOutstandingReport({
      FromDate,
      ToDate,
      organization_id,
      unit_id,
      apiHost, pdfAction
    })
      .then(data => {
        if (pdfAction == "view") {
          let encodeData = encodeURI(data);
          setTimeout(() => {

            let pdfWindow = window.open("_blank");
            // pdfWindow.document.write("<iframe width='100%' height='100%' src='data:application/pdf;base64, " + encodeData + "'></iframe>")
            pdfWindow.document.write("<embed width='100%' height='100%' src='data:application/pdf;base64, " + encodeData + "#toolbar=0&navpanes=0&scrollbar=0'></embed>")

          }, 2000)
        }

      }).catch(err => {
        console.log("eeeeeeeee", err)
      })
  }
  return (
    <>
      <Table bordered columns={getTableCols()} dataSource={getTableData()}
        pagination={false} size="small"
        // style={{ maxWidth: 'calc(100vw - 24px)', maxHeight: 'calc(100vh - 230px)' }}
        style={{ maxWidth: 'calc(100vw - 24px)' }}
        scroll={{ x: 'calc(100vw - 200px)', y: window.innerWidth <= 768 ? 'calc(100vh - 27px)' : 'calc(100vh - 270px)' }}
      />
      {
        apiData && apiData.length > 0 && objUrl !== null &&
        <>
          <div className="downloadBtn">
            <div style={{
              width: "150px",
              float: "right",
              padding: "5px",
              cursor: "pointer", fontWeight: 'bold'
            }}>

              <Button type="primary" icon={<FilePdfOutlined />} onClick={() => { setIsPdfVisible(true) }}>View  PDF </Button>
            </div>


            <div style={{
              width: "150px",
              float: "right",
              padding: "5px",
              cursor: "pointer", fontWeight: 'bold', clear: "both"
            }}>

              <Button type="primary" icon={<DownloadOutlined />} onClick={() => { downloadPdf() }}> Download  PDF </Button>
            </div>
            <Modal
              // title={`${modalTextValue.split("::")[0]} || ${modalTextValue.split("::")[1]} `}
              centered
              visible={isPdfVisible}
              destroyOnClose={true}
              maskClosable={true}
              footer={null}
              onOk={() => {

                setIsPdfVisible(false)
                Modal.destroyAll();
              }}
              closable={true}
              onCancel={() => {

                setIsPdfVisible(false)
                Modal.destroyAll();
              }}
              width={window.innerWidth < 768 ? "98%" : "888px"}
              className="viewPdfModal"
            >
              <>

                <Viewer fileUrl={objUrl} />
              </>
            </Modal>
          </div>

        </>
      }
    </>
  )
}

export default DailyOutstandingsTable