import React, { useState, useEffect } from 'react';
import moment from 'moment';
import { message } from 'antd';
import DailyDashboard from './DailyView/DailyDashboard'
import MonthlyDashboard from './MonthlyView/MonthlyDashboard'
import LoadingSvg from './Layout/LoadingSvg'
import getXformedDailyDataString from './utils/XformedDailyData'
import GetApiData from './utils/GetApiData'
import YdayDash from "./Pocs/YdayDash";

const RenderWhichReportWithData = ({ pickerType, startPeriod, endPeriod, unitId, setZoomedIn, zoomedIn, apiHost, organizationId,
  unitName, unitList, resetP, currencyInfo, renderReports }) => {
  console.log(renderReports, "rennnnn")

  let dbFromDate, dbToDate;

  const reset = () => {

    resetP()
  }
  const [apiDataReady, setApiDataReady] = useState(false);
  const [isPickerTypechng, setisPickerTypechng] = useState(pickerType);
  const [isRenderReportchng, setIsRenderReportChng] = useState(renderReports)
  // const [xformedData, setXformedData] = useState(getXformedDailyDataString())
  const [apiData, setApiData] = useState();
  const [dashboardApiData, setDashboardApiData] = useState(null);
  const [xformedData, setXformedData] = useState();
  const [isError, setISError] = useState(false)


  const [RevCollExAdmitDisPatientsTotal, setRevCollExAdmitDisPatientsTotal] = useState(null)
  const changeDashBoard = (dName) => {
    console.log(dName, "dddddddddd", startPeriod)
    pickerType = dName;

  }
  console.log(isPickerTypechng, "isPickerTypechnglllll")
  console.log(pickerType, "ptypepppp")
  if (pickerType === 'yesterday') {

    dbFromDate = moment(new Date()).subtract(1, 'days');
    dbToDate = moment(new Date()).subtract(1, 'days');
    console.log(pickerType, "k11111", dbFromDate, dbToDate)
  } else if (pickerType == 'lastSevenDays') {
    dbFromDate = moment(new Date()).subtract(7, 'days');
    dbToDate = moment(new Date()).subtract(1, 'days');
    console.log(pickerType, "k1", dbFromDate, dbToDate)
  } else if (pickerType == 'date') {
    dbFromDate = new Date(startPeriod)
    dbToDate = new Date(endPeriod)
    console.log(pickerType, "k1", dbFromDate, dbToDate)
  } else if (pickerType == 'month') {
    dbFromDate = new Date(startPeriod);
    dbToDate = new Date(endPeriod);
    console.log(pickerType, "k1", dbFromDate, dbToDate)
  }


  useEffect(() => {
    setIsRenderReportChng(renderReports);
  }, [renderReports])


  console.log(isRenderReportchng, "isccch")


  const getAPI_Cl = async () => {
    console.log(unitName, "getapiunitname")
    setApiDataReady(false)
    if (pickerType == "yesterday" || isRenderReportchng == true) {
      if (unitName == "Dashboard") {

        let finalDashBoardObj = {}
        let dateType = 'YYYY-MM-DD';
        if (pickerType == 'month') {
          dateType = 'YYYY-MM'
        }
        let FromDate = dbFromDate;
        let ToDate = dbToDate;
        let organisationId = +localStorage.getItem("organisationId");
        // let bedList = await GetApiData.getDashboardBedOccupancy({
        //   FromDate,
        //   ToDate,
        //   apiHost,
        //   organisationId,
        //   dateType
        // }).then(data => {
        //   console.log(data, "dboarddataaaaa")
        //   // setApiData(data);
        //   // setApiDataReady(true);
        //   setDashboardApiData(data);
        //   finalDashBoardObj = {
        //     bedOccupancy: data
        //   }
        // }).catch(err => {
        //   console.log("eeeeeeeee", err)
        // })

        let totalCount = await GetApiData.getDashboardDetailsfn({
          FromDate,
          ToDate,
          apiHost,
          organisationId,
          dateType
        }).then(data => {
          console.log(data, "dboarddataaaaa")
          // setApiData(data);
          // setApiDataReady(true);
          setRevCollExAdmitDisPatientsTotal(data);
          finalDashBoardObj = {
            ...finalDashBoardObj,
            revColExAdmtDisPtntTot: data
          }
          setDashboardApiData(data);
          setISError(false)
        }).catch(err => {
          setISError(true)
          errorFn()
          console.log("eeeeeeeee", err)
        })

        // setDashboardApiData(finalDashBoardObj)
        setisPickerTypechng(isPickerTypechng)
      }

      console.log(pickerType, unitName, "in fn")
      if ((pickerType === 'yesterday' || pickerType === 'date' || pickerType === 'lastSevenDays')) {
        let fromDate, toDate;

        if (pickerType === 'yesterday') {
          fromDate = moment(new Date()).subtract(1, 'days');
          toDate = moment(new Date()).subtract(1, 'days');
          console.log(fromDate, toDate, "ydatttt", pickerType)
        } else if (pickerType === 'lastSevenDays') {
          fromDate = moment(new Date()).subtract(7, 'days');
          toDate = moment(new Date()).subtract(1, 'days');

          console.log(fromDate, toDate, "ydatttt", pickerType)
        } else {
          fromDate = new Date(startPeriod)
          toDate = new Date(endPeriod)

          console.log(fromDate, toDate, "ydatttt", pickerType)
        }
        organizationId = localStorage.getItem("organizationId");
        console.log(pickerType, organizationId, unitId, fromDate, toDate, apiHost, "pppppppppyy")
        await GetApiData.daily({ organizationId, unitId, fromDate, toDate, apiHost })
          .then(data => {
            console.log(data, "allunittest")
            setXformedData(getXformedDailyDataString(data))
            setApiData(data)
            setApiDataReady(true);
            setISError(false)
          }).catch(err => {
            setISError(true);
            errorFn()
            console.log("eeeeeeeee2121", err.name)
          })
      } else if (pickerType === 'month') {
        let startMonth = new Date(startPeriod), endMonth = new Date(endPeriod)
        await GetApiData.monthly({ organizationId, unitId, startMonth, endMonth, apiHost })
          .then(data => {
            // console.log(data)
            // setXformedData(getXformedDailyDataString(data))
            setApiData(data)
            setApiDataReady(true)
            setISError(false)
          }).catch(err => {
            setISError(true);
            errorFn()
            console.log("eeeeeeeee2121", err.name)
          })
      }
    }
  }

  useEffect(async () => {

    console.log(pickerType, unitName, "ttttyyu")
    getAPI_Cl()

  }, [isRenderReportchng])

  const errorFn = () => {
    message.error('Something went wrong.Please try again later');
  };



  return (
    <>

      {!apiDataReady && !isError && <p><LoadingSvg /></p>}

      {
        apiData && unitName == 'Dashboard' && apiDataReady &&
        <YdayDash
          data={xformedData}
          apiData={apiData}
          dashboardApiData={dashboardApiData}
          startPeriod={startPeriod}
          endPeriod={endPeriod}
          dBoard_frmDate={dbFromDate}
          dBoard_toDate={dbToDate}
          firstunitId={unitId}
          setZoomedIn={setZoomedIn}
          zoomedIn={zoomedIn}
          unitName={unitName}
          unitList={unitList}
          currencyInfo={currencyInfo}
          apiHost={apiHost}
          organizationId={organizationId}
          pickerType={pickerType}
          Login={true}
          changeDashBoard={changeDashBoard} reset={reset}
        />
      }
      {
        // apiDataReady && (pickerType === 'date' || pickerType == 'lastSevenDays') && 
        apiDataReady && (pickerType === 'date' || pickerType == 'lastSevenDays' || pickerType == 'yesterday') && unitName != 'Dashboard' &&

        <DailyDashboard
          data={xformedData}
          apiData={apiData} startPeriod={startPeriod} endPeriod={endPeriod} firstunitId={unitId} setZoomedIn={setZoomedIn} zoomedIn={zoomedIn}
          unitName={unitName} unitList={unitList} currencyInfo={currencyInfo} apiHost={apiHost} organizationId={organizationId} pickerType={pickerType} Login={true}
          changeDashBoard={changeDashBoard} reset={reset} />
      }
      {
        apiDataReady && pickerType === 'month' && unitName != 'Dashboard' &&

        <MonthlyDashboard apiData={apiData}
          startPeriod={startPeriod}
          endPeriod={endPeriod} unitId={unitId} setZoomedIn={setZoomedIn} zoomedIn={zoomedIn} unitName={unitName}
          unitList={unitList} currencyInfo={currencyInfo} apiHost={apiHost} organizationId={organizationId}
          Login={true} changeDashBoard={changeDashBoard} reset={reset} />
      }
    </>
  )
}

export default RenderWhichReportWithData;
