import React, { useState } from 'react'
import Chart from "react-apexcharts";
import moment from 'moment';

const TopDeptsLine = ({ dashboardApiData, dBoard_frmDate, dBoard_toDate, pickerType }) => {
  const [revenueData, setRevenueData] = useState(dashboardApiData.topThreeDeptByRevenue ? dashboardApiData.topThreeDeptByRevenue : null)
  const [dateListarr, setDateListArr] = useState([]);
  console.log(dashboardApiData, "apiiidata")
  const series = () => {

    console.log(pickerType, "ppptype")

    if (dateListarr.length == 1) {

      let finalArr = []
      revenueData.map((dataVar, index) => {
        // let revcount = '"' + dataVar.totalrevenue + '"';
        let revcount1 = dataVar.totalrevenue / 1000;
        console.log(revcount1, "counnnnnt")
        // let deptObj = { name: dataVar.speciality_name, data: [revcount.substring(1, 3)] }
        let deptObj = { name: dataVar.speciality_name, data: [parseFloat(revcount1).toFixed(0)] }
        finalArr.push(deptObj)
      })
      console.log(finalArr, "frrrra");
      return finalArr;
    }
    else {
      let uniqueDeptArr = [];
      console.log(revenueData, "rdata");
      let updatedRevenueData = revenueData;
      dateListarr.map((dateValue, index) => {
        let dateFind = false;
        revenueData.map((revDate, index) => {
          console.log(revDate.billdate, "dddt");
          if (revDate.billdate == 'dateValue') {
            dateFind = true;
          }

        })
        if (dateFind == false) {

        }
      })

      revenueData && revenueData.length > 0 &&
        revenueData.map((data, index) => {
          if (uniqueDeptArr.length == 0) {
            uniqueDeptArr.push(data.speciality_name)
          }
          else {
            let findBedIndex = uniqueDeptArr.findIndex((deptName, index) => {

              return deptName == data.speciality_name
            })

            if (findBedIndex == -1) {
              uniqueDeptArr.push(data.speciality_name)
            }
          }
        })

      let finalArr = [];
      console.log(dateListarr, "hhhhu")

      uniqueDeptArr.map((deptName, index) => {
        let deptObj = { name: deptName }
        let dataArr = [];
        dateListarr.map((dateValue, index) => {
          let dateFind = false;
          revenueData.map((revData, index) => {
            if (revData.billdate == dateValue) {
              if (deptName == revData.speciality_name) {
                dateFind = true;
                // let revcount = '"' + revData.totalrevenue + '"';
                let revcount1 = revData.totalrevenue / 1000;

                // dataArr.push(revcount.substring(1, 3))
                dataArr.push(parseFloat(revcount1).toFixed(0))



              }

            }
          })
          if (dateFind == false) {
            dataArr.push(0);
          }

        })
        console.log(dataArr, "dataarrr")
        deptObj = {
          ...deptObj,
          data: dataArr
        }
        console.log(deptObj, "finalonjjjjj")
        finalArr.push(deptObj)
      })
      return finalArr;
      // return [
      //   {
      //     name: "Radiology",
      //     data: [28, 29, 33, 36, 32, 32, 33]
      //   },
      //   {
      //     name: "Cardiology",
      //     data: [26, 27, 29, 31, 28, 26, 29]
      //   },
      //   {
      //     name: "Orthopaedic",
      //     data: [14, 16, 13, 17, 12, 16, 19]
      //   }
      // ]

    }
  }

  const getDateRange = () => {
    // return ['15-Jan', '16-Jan', '17-Jan', '18-Jan', '19-Jan', '20-Jan', '21-Jan']
    let uniqueDateRangeArr = []

    console.log(revenueData, "vvee", moment(dBoard_frmDate).format('YYYY-MM'));
    if (pickerType == 'month') {
      var start = moment(dBoard_frmDate).format('YYYY-MM');
      var end = moment(dBoard_toDate).format('YYYY-MM');
      console.log(start, end, "stend")
      if (start == end) {
        uniqueDateRangeArr.push(moment(dBoard_frmDate).format('YYYY-MM'));
      }
      else {
        while (start <= end) {

          var newDate = moment(start).add(1, 'months').format('YYYY-MM');
          console.log(newDate, "nnnewnextdate")
          uniqueDateRangeArr.push(start);
          start = newDate;
        }
      }
    }
    else {

      var start = moment(dBoard_frmDate).format('YYYY-MM-DD');
      var end = moment(dBoard_toDate).format('YYYY-MM-DD');
      console.log(start, end, "stend")
      if (start == end) {
        uniqueDateRangeArr.push(moment(dBoard_frmDate).format('YYYY-MM-DD'));
      }
      else {
        while (start <= end) {

          var newDate = moment(start).add(1, 'days').format('YYYY-MM-DD');
          console.log(newDate, "nnnewnextdate")
          uniqueDateRangeArr.push(start);
          start = newDate;
        }
      }
    }


    console.log(uniqueDateRangeArr, "rrrunique");

    if (dateListarr.length == 0) {
      setDateListArr(uniqueDateRangeArr)
    }

    return uniqueDateRangeArr;
  }
  const options = () => {
    return {
      chart: {
        height: 360,
        type: 'line',
        dropShadow: {
          enabled: true,
          color: '#000',
          top: 18,
          left: 7,
          blur: 10,
          opacity: 0.2
        },
        toolbar: {
          show: false
        }
      },
      colors: ['#77B6EA', '#545454', '#cf1322'],
      dataLabels: {
        enabled: true,
      },
      stroke: {
        curve: 'smooth'
      },
      title: {
        text: 'Top 3 Departments by Revenue',
        align: 'left'
      },
      grid: {
        borderColor: '#e7e7e7',
        row: {
          colors: ['#f3f3f3', 'transparent'], // takes an array which will be repeated on columns
          opacity: 0.5
        },
      },
      markers: {
        size: 1
      },
      xaxis: {
        // categories: ['15-Jan', '16-Jan', '17-Jan', '18-Jan', '19-Jan', '20-Jan', '21-Jan'],
        categories: getDateRange(),
        title: {
          text: 'Date'
        }
      },
      yaxis: {
        title: {
          text: 'Revenue (in thousand)'
        },
        min: 5,
        max: 40
      },
      // legend: {
      //   position: 'top',
      //   horizontalAlign: 'right',
      //   floating: true,
      //   offsetY: -25,
      //   offsetX: -5
      // }
    }
  }

  return (
    <div id="wrapper">
      <div id="chart-line">
        <Chart options={options()} series={series()} type="line" height={380} />
      </div>
    </div>
  );

}

export default TopDeptsLine