import React from 'react'
import { Tabs } from 'antd';
import Chart from "react-apexcharts"

class DebtorChart extends React.Component {
  constructor(props) {
    super(props);

    this.state = {

      series: [{
        data: [400, 430, 448, 1200, 1380]
      }],
      options: {
        chart: {
          type: 'bar',
          height: 380
        },
        plotOptions: {
          bar: {
            barHeight: '100%',
            distributed: true,
            horizontal: true,
            dataLabels: {
              position: 'bottom'
            },
          }
        },
        colors: ['#33b2df', '#546E7A', '#d4526e', '#13d8aa', '#A5978B'],
        dataLabels: {
          enabled: true,
          textAnchor: 'start',
          style: {
            colors: ['#fff']
          },
          formatter: function (val, opt) {
            return opt.w.globals.labels[opt.dataPointIndex] + ":  " + val
          },
          offsetX: 0,
          dropShadow: {
            enabled: true
          }
        },
        stroke: {
          width: 1,
          colors: ['#fff']
        },
        xaxis: {
          categories: ['Eco Focus', 'Strat Corp.', 'Sanguine', 'Sporadic Sys', 'Ferrets Pvt'],
        },
        yaxis: {
          labels: {
            show: false
          }
        },
        title: {
          text: 'Debtors',
          align: 'center',
          floating: true
        },
        subtitle: {
          text: 'Figures in thousands',
          align: 'center',
        },
        tooltip: {
          theme: 'dark',
          x: {
            show: false
          },
          y: {
            title: {
              formatter: function () {
                return ''
              }
            }
          }
        }
      },


    };
  }



  render() {
    return (


      <div id="chart">
        <Chart options={this.state.options} series={this.state.series} type="bar" height={380} />
      </div>


    );
  }
}

