const { TabPane } = Tabs;
const DebtorCreditor = () => {

  return (
    <Tabs type="card">
      <TabPane tab="Overview" key="1">
        <OverviewChart />
      </TabPane>
      <TabPane tab="Creditors" key="2">
        <CreditChart />
      </TabPane>
      <TabPane tab="Debtors" key="3">
        <DebtorChart />
      </TabPane>
    </Tabs>
  )
}

export default DebtorCreditor