import React, { useState, useEffect } from 'react';
import Chart from 'react-apexcharts';


const PatientTypeRadial = ({ dBoard_frmDate, dBoard_toDate, apiHost, organizationId, pickerType, dashboardApiData }) => {
  console.log(dashboardApiData, "ptrrr")



  console.log("ptypeRadialll", dashboardApiData)
  let bedCategoryListArr = [];
  let percentageArr = [];
  console.log(dashboardApiData, "ptypeRadialll")
  if (dashboardApiData && dashboardApiData.length > 0) {
    console.log(dashboardApiData, "ddddd")
    dashboardApiData.map((bedObj, index) => {
      if (bedCategoryListArr.length == 0) {
        bedCategoryListArr.push(bedObj.bedCategoryDesc)
      }
      else {
        let findBedIndex = bedCategoryListArr.findIndex((bed, index) => {

          return bed.replace(/\s+/g, '').toLowerCase() == bedObj.bedCategoryDesc.replace(/\s+/g, '').toLowerCase()
        })

        if (findBedIndex == -1) {
          bedCategoryListArr.push(bedObj.bedCategoryDesc)
        }
      }

    })


  }
  const getSeries = () => {

    bedCategoryListArr.map((bedType, index) => {
      let totalPercentage = 0
      dashboardApiData.map((apiBedObj, index) => {
        if (apiBedObj.bedCategoryDesc.replace(/\s+/g, '').toLowerCase() == bedType.replace(/\s+/g, '').toLowerCase()) {
          totalPercentage += (+apiBedObj.percentage)
        }
      })
      percentageArr.push(totalPercentage)
    })



    // return [60, 40, 56, 87]
    return percentageArr;
  }


  const getOptions = () => {
    return {
      chart: {
        height: 350,
        type: 'radialBar',
      },
      title: {
        text: 'Room Occupancy by %'
      },
      legend: { show: true, position: 'bottom' },
      plotOptions: {
        radialBar: {
          dataLabels: {
            name: {
              fontSize: '22px',
            },
            value: {
              fontSize: '16px',
            },
            total: {
              show: true,
              label: 'Total',
              formatter: function (w) {
                // By default this function returns the average of all series. The below is just an example to show the use of custom formatter function
                if (percentageArr.length > 0) {
                  console.log(percentageArr, "pppyu")
                  const avg_of_percent = parseFloat(percentageArr.reduce((a, b) => (a + b)) / percentageArr.length).toFixed(2);
                  return avg_of_percent + '%'

                }
                else {
                  return 0 + '%'
                }

              }
            }
          }
        }
      },
      labels: bedCategoryListArr,
    }
  }

  return <Chart options={getOptions()} series={getSeries()} type="radialBar" height={320} />

}

export default PatientTypeRadial