import React from 'react'
import DailyOverviewChart from "../DailyView/DailyOverviewChart"
import AlosChartDash from "./AlosChartDash"
import TopDeptsLine from "./TopDeptsLine"
import ArpbChartDash from "./ArpbChartDash"
import DynamicRevenue from "./DynamicRevenue"
import { Row, Col, Statistic, Card } from "antd"
import DebtorCreditor from "./DebtorCreditor"

const YdayDash = ({ apiData, currencyInfo, startPeriod, endPeriod, firstunitId, apiHost, organizationId, pickerType,
  dBoard_frmDate, dBoard_toDate, dashboardApiData }) => {

  return (
    <>
      <DailyOverviewChart
        isPoc={true} apiData={apiData} currencyInfo={currencyInfo}
        dBoard_frmDate={dBoard_frmDate} dBoard_toDate={dBoard_toDate}
        apiHost={apiHost} organizationId={organizationId}
        pickerType={pickerType}
        dashboardApiData={dashboardApiData}
      />
      <br />
      <Row gutter={16}>
        <Col span={8}>
          <Card style={{ borderLeft: "4px solid #3399FF" }} className="card-box-shadow col-chart-bg">
            {
              console.log(dashboardApiData.avgStayRevbyDeptNBed[0].avg_length_of_stay, "bsdcon")
            }
            <Statistic
              title="Avg. Length of Stay"
              value={dashboardApiData && dashboardApiData.avgStayRevbyDeptNBed && dashboardApiData.avgStayRevbyDeptNBed[0].avg_length_of_stay ? dashboardApiData.avgStayRevbyDeptNBed[0].avg_length_of_stay : 0}
              precision={2}
              suffix="days"
              valueStyle={{ color: '#3399FF' }}
            />
          </Card>
        </Col>
        <Col span={8} >
          <Card style={{ borderLeft: "4px solid #4e4e4e" }} className="card-box-shadow col-chart-bg">
            <Statistic
              title="Avg. Revenue by Dept."
              value={dashboardApiData && dashboardApiData.avgStayRevbyDeptNBed && dashboardApiData.avgStayRevbyDeptNBed[0].avg_revenue_by_dept ? dashboardApiData.avgStayRevbyDeptNBed[0].avg_revenue_by_dept : 0}
              precision={2}
              valueStyle={{ color: '#4e4e4e' }}
              formatter={value => currencyInfo + " " + new Intl.NumberFormat('en-IN').format(value)
                //  new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(value)
              }
            />
          </Card>
        </Col>
        <Col span={8} >
          <Card style={{ borderLeft: "4px solid #8000ff" }} className="card-box-shadow col-chart-bg">
            <Statistic
              title="Avg. Revenue by Bed"
              value={dashboardApiData && dashboardApiData.avgStayRevbyDeptNBed && dashboardApiData.avgStayRevbyDeptNBed[0].revenue_by_bed ? dashboardApiData.avgStayRevbyDeptNBed[0].revenue_by_bed : 0}
              precision={2}
              valueStyle={{ color: '#8000ff' }}
              formatter={value => currencyInfo + " " + new Intl.NumberFormat('en-IN').format(value)
                //  new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(value)
              }
            />
          </Card>
        </Col>
      </Row>
      <br />
      <Row gutter={16}>
        <Col span={8} >
          <Card className={"col-chart-bg"} hoverable>
            <AlosChartDash />
          </Card>
        </Col>
        <Col span={8} >
          {
            console.log("yyyyday1", dashboardApiData)
          }
          <Card className={"col-chart-bg"} hoverable >
            <TopDeptsLine dashboardApiData={dashboardApiData ? dashboardApiData : null}
              dBoard_frmDate={dBoard_frmDate}
              dBoard_toDate={dBoard_toDate}
              pickerType={pickerType}
            />
          </Card>
        </Col>
        <Col span={8}>
          <Card className={"col-chart-bg"} hoverable>
            <ArpbChartDash />
          </Card>
        </Col>
      </Row>

      <br />

      <Row gutter={16}>
        <Col span={12}>
          <Card className={"col-chart-bg"} hoverable>
            <DynamicRevenue />
          </Card>
        </Col>
        <Col span={12}>
          <Card className={"col-chart-bg"} hoverable>
            <DebtorCreditor />
          </Card>
        </Col>
      </Row>

    </>
  )
}

export default YdayDash